<?php

declare(strict_types=1);

namespace Dopple;

use Dopple\CrawlerResponses\CrawlerResponse;
use Dopple\CrawlerResponses\NotFound;
use Dopple\CrawlerResponses\Redirect;

/**
 * Apache config for the mirror. Needs `AllowOverride FileInfo Indexes`.
 */
final class HtaccessBuilder
{
    /**
     * @param array<string, string> $sharedHeaders Header name => value, sent on every response
     */
    public function build(CrawlerResponses $crawledResources, array $sharedHeaders = []): string
    {
        $lines = [
            <<<'HTACCESS'
                # Generated by Dopple

                DirectorySlash Off
                RewriteEngine On
                RewriteBase /
                HTACCESS,
            '',
        ];

        if ($sharedHeaders !== []) {
            $lines[] = '# Headers shared by every crawled page';

            foreach ($sharedHeaders as $name => $value) {
                $lines[] = 'Header always set ' . $name . ' "' . addcslashes($value, '"\\') . '"';
            }

            $lines[] = '';
        }

        foreach ($crawledResources as $crawledResource) {
            if ($crawledResource instanceof Redirect) {
                $lines[] = $this->redirect($crawledResource);
            }
        }

        $resourcesWithQueryStrings = iterator_to_array($crawledResources, false)
            |> array_filter(?, static fn (CrawlerResponse $resource): bool => !$resource instanceof Redirect)
            |> array_filter(
                ?,
                static function (CrawlerResponse $resource): bool {
                    return $resource->originalUrl->getQuery() !== null &&
                        $resource->originalUrl->getQuery() !== '';
                },
            );

        if ($resourcesWithQueryStrings !== []) {
            $lines[] = '';
            $lines[] = '# Query string variants';

            foreach ($resourcesWithQueryStrings as $variant) {
                $query = $this->escapeForApacheRegex($variant->originalUrl->getQuery());
                $path = $this->escapeForApacheRegex(ltrim(rawurldecode($variant->originalUrl->getPath()), '/'));
                $file = ltrim(FileStore::makeFilePathForStorage($variant), '/');

                $lines[] = <<<HTACCESS
                    RewriteCond %{QUERY_STRING} ^{$query}$
                    RewriteRule ^{$path}$ {$file} [L,QSD]
                    HTACCESS;
            }
        }

        foreach ($crawledResources as $crawledResource) {
            if ($crawledResource instanceof NotFound) {
                $lines[] = '';
                $lines[] = 'ErrorDocument 404 /' . NotFound::FILE_PATH;

                break;
            }
        }

        $lines[] = '';
        $lines[] = <<<'HTACCESS'
            # /contact and /contact/ serve contact.html, unless contact/ has an index.html
            RewriteCond %{REQUEST_FILENAME} !-f
            RewriteCond %{REQUEST_FILENAME}/index.html !-f
            RewriteCond %{REQUEST_FILENAME} ^(.+?)/?$
            RewriteCond %1.html -f
            RewriteRule ^(.+?)/?$ $1.html [L]
            HTACCESS;

        return implode("\n", $lines) . "\n";
    }

    private function redirect(Redirect $redirect): string
    {
        $path = $this->escapeForApacheRegex(ltrim(rawurldecode($redirect->from->getPath()), '/'));
        $target = str_replace(' ', '%20', $redirect->to->toRawString());

        if ($redirect->from->getQuery() === null || $redirect->from->getQuery() === '') {
            return 'RedirectMatch 301 ^/' . $path . '$ ' . $target;
        }

        $query = $this->escapeForApacheRegex($redirect->from->getQuery());

        return <<<HTACCESS
            RewriteCond %{QUERY_STRING} ^{$query}$
            RewriteRule ^{$path}$ {$target} [R=301,L,QSD]
            HTACCESS;
    }

    /**
     * Escapes regex metacharacters and spaces so the value matches literally in an Apache directive argument.
     */
    private function escapeForApacheRegex(string $value): string
    {
        return str_replace(' ', '\x20', preg_quote($value));
    }
}
